L000779	\section{Proof of Result 2: The Nontriviality of Witnesses}\label{appendix: nontrivial}
L000780	We prove Result 2 by the following equivalent statement: $\mathcal{V}_{g}(\boldsymbol{O})=0 ~~\forall\boldsymbol{O}$ if and only if there exists an affine functional $L$ such that $g(O_{\rm ext})=L(O_{\rm ext})$.
L000781	Moreover, let $\psi\in O_{\rm ext}$.
L000782	\begin{proof}---We start by analyzing the \textit{if} direction, we have $g(O_{\rm ext})=L(O_{\rm ext})=F_{g}(O_{\rm ext})$, such that $L(\sum_i p_i O_i)=\sum_i p_i L(O_i)$ for all decompositions.
L000783	Then
L000784	\begin{equation}
L000785	\begin{aligned}
L000786	    \max_{\boldsymbol{O}} \mathcal{V}_{g}(\boldsymbol{O})
L000787	    &=\max_{\{p(a|x),\psi_{a|x}\}_{a,x}} \left\{ \max_{x} \sum_{a} p(a|x) g(O_{a|x}) - \min_{x} \sum_{a} p(a|x)F_{g}(O_{a|x}) ,0 \right\} \\
L000788	    &\leq  \max\left\{\max_{\{p(a|x),\psi_{a|x}\}_{a,x}} \sum_{a} p(a|x) g(\psi_{a|x}) - \min_{\{p(a|x),\psi_{a|x}\}_{a,x}} \sum_{a} p(a|x)L(\psi_{a|x}) ,0\right\} \\
L000789	    &=  \max_{\{p(a|x),\psi_{a|x}\}_{a,x}} \sum_{a} p(a|x) L(\psi_{a|x}) - \min_{\{p(a|x),\psi_{a|x}\}_{a,x}} \sum_{a} p(a|x)L(\psi_{a|x})  \\
L000790	    &=  \max_{\{p(a|x),\psi_{a|x}\}_{a}} L\left[\sum_{a} p(a|x)\psi_{a|x}\right] - \min_{\{p(a|x),\psi_{a|x}\}_{a}} L\left[\sum_{a} p(a|x)\psi_{a|x}\right] \\
L000791	    &=  \max_{\{p(a|x),\psi_{a|x}\}_{a}}L(O^{\rm m}) - \min_{\{p(a|x),\psi_{a|x}\}_{a}} L(O^{\rm m}) \\
L000792	    &= 0,
L000793	\end{aligned}
L000794	\end{equation}
L000795	where, in the first line, the maximum taken over all assemblages $\boldsymbol{O}$ becomes the best decomposition of $\{p(a|x),\psi_{a|x}\}$ and taking the positive part; the second line comes from the property of the max operation, i.e., $\max\{X-Y\}\le \max X - \min Y$; the third line results from the non-negativity of the expression; the fifth line is given by the same marginal $O^{\rm m}$ for all $x$ [no-signaling condition: $\sum_{a} p(a|x)\psi_{a|x}=O^{\rm m}~\forall x$].
L000796	We note that in this proof, we exclude the case that $g$ being affine in the whole space $\mathcal{O}$, which directly makes the inequality trivial.
L000797	
L000798	
L000799	For the ``only if'' direction, assume $\mathcal V_{g}(\boldsymbol{O})=0$ for every assemblage $\boldsymbol{O}$ and fix the assemblage $\boldsymbol{O}^{\star}$ that maximizes the quantity $\max_{x}g^{\rm as}(\boldsymbol{O}_{x})-\min_{x'}F_{g}^{\rm as}(\boldsymbol{O}_{x'})$, which implies
L000800	\begin{equation}
L000801	    \max_{x} g^{\rm as}(\boldsymbol{O}^{\star}_{x})
L000802	    \leq
L000803	    \min_{x} F_{g}^{\rm as}(\boldsymbol{O}^{\star}_{x}).
L000804	\end{equation}
L000805	Given that $g^{\rm as}(\boldsymbol{O}^{\star}_{x})$ and
L000806	$F_{g}^{\rm as}(\boldsymbol{O}^{\star}_{x})$ are the averages of
L000807	$g(\psi_{a|x})$ and $F_{g}(\psi_{a|x})$, respectively, over $\{\psi_{a|x}\}_a \subset \text{ext}(\mathcal{O})$ that decompose the same margin
L000808	$O^{\rm m}=\sum_a p(a|x)\psi_{a|x}~\forall x$. Thus, the above inequality implies
L000809	\begin{equation}
L000810	\begin{aligned}
L000811	    \max_{\{p(a|x),\psi_{a|x}\}_{a}}{\sum_a p(a|x) g(\psi_{a|x})}
L000812	    &\leq \min_{\{p(a|x),\psi_{a|x}\}_{a}}{\sum_a p(a|x) F_{g}(\psi_{a|x})}\\
L000813	    &= \min_{\{p(a|x),\psi_{a|x}\}_{a}}{\sum_a p(a|x) g(\psi_{a|x})},
L000814	\end{aligned}
L000815	\end{equation}
L000816	where the second line is given by $F_{g}(O_{\rm ext})=g(O_{\rm ext})$.
L000817	One can observe that the global maximum can not be smaller than the global minimum only if every decomposition of every admissible $O^{\rm m}$ yields the same value, i.e., the convex roof $g^{\cup}$ and the concave roof $g^{\cap}$ of $g$ coincide.
L000818	This suggests that the function $g$ is affine on $\text{ext}(\mathcal{O})$, which concludes the proof.
L000819	
L000820	\end{proof}
