L000822	\section{Examples of non-trivial inequalities for state assemblages}\label{appendix: examples}
L000823	Here, we provide two non-trivial examples of constructing incompatibility witnesses by a convex functional $g$.
L000824	We start by recalling the definition of the Wigner-Yanase skew information~\cite{Wigner1963,Luo2003prl}:
L000825	\begin{equation}
L000826	\begin{aligned}
L000827	    I(\rho,H)
L000828	    :=& - \frac{1}{2}\Tr[\sqrt{\rho},H]^{2} \\
L000829	    =&  \Tr \rho H^2 - \Tr \sqrt{\rho}H\sqrt{\rho}H,
L000830	\end{aligned}
L000831	\end{equation}
L000832	which is convex for states~\cite{Takagi2019sr}.
L000833	Then, we have
L000834	\begin{equation}
L000835	\begin{aligned}
L000836	    F_{I}(\rho,H)
L000837	    :=& \sup \sum_{i} p_i I(\psi_i ,H)\\
L000838	    =& \sup \sum_{i} p_i \left[ \bra{\psi_i}H^2 \ket{\psi_i} - \bra{\psi_i}H \ket{\psi_i}\bra{\psi_i}H \ket{\psi_i} \right] \\
L000839	    =& \sup \sum_{i} p_i \text{Var}(\psi_i ,H) \\
L000840	    =& \text{Var}(\rho ,H),
L000841	\end{aligned}
L000842	\end{equation}
L000843	where $\text{Var}(\rho ,H)$ is the variance of observable $H$, i.e., $\text{Var}(\rho,H)=\Tr(\rho H^2)-(\Tr\rho H)^2$, and the forth line is due to variance is its own concave roof~\cite{Toth2013pra}.
L000844	Therefore, the violation of $I$ can be given by
L000845	\begin{equation}
L000846	    \mathcal{S}_I(\boldsymbol{\sigma})=\max \{\max_x I^{\rm as}(\boldsymbol{\sigma}_x) - \min_x {\rm Var}^{\rm as}(\boldsymbol{\sigma}_x),0 \}.\label{eq: skew witness}
L000847	\end{equation}
L000848	
L000849	The second illustrative example is the squared $\ell_2$-type of coherence for a given basis $\{\ket{i}\}_i$, which is defined as~\cite{Baumgratz2014PRL}
L000850	\begin{equation}
L000851	\begin{aligned}
L000852	    N(\rho,\boldsymbol{\Pi})
L000853	    :=& \sum_{i\neq j} |\bra{i} \rho \ket{j}|^2\\
L000854	    =& \sum_{i,j} \bra{i}\rho\ket{j}\bra{j}\rho\ket{i}-\sum_i \bra{i}\rho\ket{i}\bra{i}\rho\ket{i} \\
L000855	    =& \sum_i \Tr~\rho^2\Pi_i-\Tr~\rho\Pi_i\rho\Pi_i, \label{eq: l2 norm}
L000856	\end{aligned}
L000857	\end{equation}
L000858	where $\boldsymbol{\Pi}=\{\Pi_i = \ket{i}\bra{i}\}_i$ and its concave extension reads
L000859	\begin{equation}
L000860	\begin{aligned}
L000861	    F_N(\rho,\boldsymbol{\Pi})
L000862	    :=& \sup \sum_i p_i N(\psi_i,\boldsymbol{\Pi})\\
L000863	    =& \sup \sum_i p_i \left(\sum_j\bra{\psi_i}\Pi_j\ket{\psi_i} - \bra{\psi_i}\Pi_j\ket{\psi_i}\bra{\psi_i}\Pi_j\ket{\psi_i}\right)\\
L000864	    =& \sup \sum_i p_i \sum_j{\rm Var}(\psi_i , \Pi_j)\\
L000865	    =& \sum_j{\rm Var}(\rho , \Pi_j)\\
L000866	    :=& \overline{\rm Var}(\rho,\boldsymbol{\Pi}). \label{eq: F_N}
L000867	\end{aligned}
L000868	\end{equation}
L000869	The corresponding violation degree reads
L000870	\begin{equation}
L000871	    \mathcal{S}_N(\boldsymbol{\sigma})=\max \{\max_x N^{\rm as}(\boldsymbol{\sigma}_x) - \min_x \overline{\rm Var}^{\rm as}(\boldsymbol{\sigma}_x),0 \}.
L000872	\end{equation}
L000873	
L000874	
L000875	Additionally, we wish to emphasize that these functionals, i.e., the WYSI and $\ell_2$-type coherence, are experimental accessible, as they can be estimated without requiring full quantum state tomography.
L000876	As shown in Ref.~\cite{Girolami2014prl}, the lower bound of WYSI, $I^{L}(\rho,H)$, is directly measurable:
L000877	\begin{equation}
L000878	    I^{L}(\rho,H) = -\frac{1}{4}\Tr[\rho,H]^2\le I(\rho,H).
L000879	\end{equation}
L000880	This indicates we can use this lower bound to construct a measurable witness that is sufficient to demonstration the violation of $\mathcal{S}_I$ in Eq.~\eqref{eq: skew witness}.
L000881	
L000882	Furthermore, we note that this lower bound $I^{L}(\rho,H)$ is directly related to the $\ell_{2}$-type coherence $N(\rho,\boldsymbol{\Pi})$ by replacing the observable $H$ with a set of projective measurements $\boldsymbol{\Pi}=\{\Pi_{i}\}_{i}$. Specifically:
L000883	\begin{equation}
L000884	\begin{aligned}
L000885	    N(\rho,\boldsymbol{\Pi})
L000886	    &= \sum_{i \neq j} |\bra{i}\rho\ket{j}|^2 \\
L000887	    &= \sum_i \Tr \,\rho^2 \Pi_i - \Tr\, \rho \Pi_i \rho\Pi_i \\
L000888	    &= \sum_i 2\, I^{L}(\rho,\Pi_i).
L000889	\end{aligned}
L000890	\end{equation}
L000891	Consequently, both witnesses are physically measurable, rendering them highly practical for experimental implementation.
L000892	
L000893	
