L000962	\section{Proof of Result 4: A valid incompatibility monotone}\label{appendix: measurement assemblage}
L000963	
L000964	We first show that when the shared state $\ket{\psi^{AB}}=\sum_i \sqrt{p_i} \ket{i}\ket{i}$ is full-ranked such that $\rho^{\rm B}= \Tr_{\rm A} \ket{\psi^{AB}}\bra{\psi^{AB}} = \sum_i p_i \ket{i}\bra{i}$, the SEO $\boldsymbol{B}=\{B_{a|x}\}_{a,x}$ is equivalent to Alice's measurement $\boldsymbol{M}=\{M_{a|x}\}_{a,x}$ up to its transpose, which is
L000965	\begin{equation}
L000966	\begin{aligned}
L000967	    B_{a|x}
L000968	    &= (\rho^{\rm B})^{-1/2} \,\sigma_{a|x}(\rho^{\rm B})^{-1/2} \\
L000969	    &= \sum_m p_m^{-1/2} \ket{m}\bra{m}\left[ \text{Tr}_{A} ~(M_{a|x}\otimes \id )\sum_{i,j}\sqrt{p_i p_j} \ket{i}\bra{j} \otimes \ket{i}\bra{j} \right] \sum_n p_n^{-1/2} \ket{n}\bra{n}\\
L000970	    &=   \sum_{i,j,m,n} \sqrt{ q_i q_j} \, p_m^{-1/2}p_n^{-1/2}\bra{j} M_{a|x} \ket{i} \ket{m} \braket{m|i}\braket{j|n}\bra{n} \\
L000971	    &= \sum_{m,n} \bra{m}M_{a|x}^{T}\ket{n}\ket{m}\bra{n} \\
L000972	    &=  M_{a|x}^{T},
L000973	\end{aligned}
L000974	\end{equation}
L000975	where the second line holds due to $\ket{\psi^{AB}}$ is full-ranked, such that $p_i >0 ~~\forall i$.
L000976	In the following, thus, we replace the SEO input $\boldsymbol{B}$ by the Alice measurement assemblage $\boldsymbol{M}$.
L000977	
L000978	According to Ref.~\cite{Paul2019prl}, $\mathcal{M}_{g}(\boldsymbol{M})$ is a valid incompatibility monotone if it satisfies:
L000979	\begin{itemize}
L000980	    \item[(a)] $\mathcal{M}_{g}(\boldsymbol{M})=0$, if $\boldsymbol{M}$ is jointly measurable.
L000981	    \item[(b)] $\mathcal{M}_{g}(\boldsymbol{M})$ satisfies convexity.
L000982	    \item[(c)] $\mathcal{M}_{g}(\boldsymbol{M})$ is non-increasing under post-processing, namely
L000983	    \begin{equation}
L000984	    M_{a'|x'}=
L000985	    \mathcal{W}(M_{a|x}) = \sum_{a,x}p(x|x')p(a'|a,x,x')M_{a|x}\quad \forall a,x,\label{eq: wiring map for measurements}
L000986	    \end{equation}
L000987	\end{itemize}
L000988	where $ \mathcal{W}$ denotes post-processing with the conditional probabilities $p(x|x')$ and $p(a'|a,x,x')$~\cite{Gallego2015prx}.
L000989	
L000990	The condition (a) is automatically satisfied by the definition of $\mathcal{M}_{g}$:
L000991	\begin{equation}
L000992	    \mathcal{M}_{g}(\boldsymbol{M}) = \sup_{\rho_B} \mathcal{S}_{g}[\sqrt{\rho_B}\,\boldsymbol{M} \sqrt{\rho_B}].
L000993	\end{equation}
L000994	Given that a measurement assemblage $\boldsymbol{M}$ is compatible if and only if its SEO induced a state assemblage $\boldsymbol{\sigma} = \sqrt{\rho_B} \,\boldsymbol{M} \sqrt{\rho_B}$ that can be described by an LHS model.
L000995	Thus, we conclude that $\mathcal{M}_{g}(\boldsymbol{M})=0$ if $\boldsymbol{M}$ is compatible.
L000996	
L000997	
L000998	
L000999	For the condition (b) $\mathcal{M}_{g}(\boldsymbol{M})$ satisfies convexity, we only need to demonstrate $\mathcal{S}_{g}({\boldsymbol{\sigma}})$ is convex in assemblage.
L001000	To show this, let us consider a state assemblage
L001001	\begin{equation}
L001002	\boldsymbol{\sigma}
L001003	\to q\boldsymbol{\sigma}+(1-q)\boldsymbol{\sigma}^{\prime}
L001004	:=\{q\sigma_{a|x}+(1-q)\sigma_{a|x}^{\prime}\}_{a,x}\quad \forall q \in [0,1].
L001005	\end{equation}
L001006	Given $g$ is convex, its assemblage version $g^{\rm as}$ is naturally convex, i.e.,
L001007	\begin{equation}
L001008	\begin{aligned}
L001009	    g^{\rm as}(\boldsymbol{\sigma})
L001010	    &\to g^{\rm as}\left[ q\boldsymbol{\sigma} + (1-q)\boldsymbol{\sigma}' \right] \\
L001011	    &= \max_{x}   \sum_a p(a|x) g\left[ q\rho_{a|x} + (1-q)\rho'_{a|x}\right] \\
L001012	    &\leq \max_{x} \sum_a \left[ q p(a|x)g(\rho_{a|x}) + (1-q)p'(a|x)g(\rho'_{a|x}) \right] \\
L001013	    &\leq q \max_{x}  \sum_a p(a|x)g(\rho_{a|x})
L001014	     + (1-q) \max_{x} \sum_a p'(a|x)g(\rho'_{a|x}) \\
L001015	    &= q g^{\rm as}(\boldsymbol{\sigma}) + (1-q) g^{\rm as}(\boldsymbol{\sigma}').
L001016	\end{aligned}
L001017	\end{equation}
L001018	
L001019	Analogously, with the fact that the $F_{g}(\rho)$ is concave, we have that $F_{g}^{\rm as}(\boldsymbol{\sigma})$ is also concave with respect to a combination of the state assemblages $q\boldsymbol{\sigma}+(1-q)\boldsymbol{\sigma}^{\prime}$.
L001020	
L001021	Then, we can show that the violation degree satisfies convexity, namely
L001022	\begin{equation}
L001023	\begin{aligned}
L001024	    \mathcal{S}_{g}(\boldsymbol{\sigma})
L001025	    &\to \mathcal{S}_{g}\left[ q\boldsymbol{\sigma}+(1-q)\boldsymbol{\sigma}' \right] \\
L001026	    &= \max \left\{ g^{\rm as}[q\boldsymbol{\sigma}+(1-q)\boldsymbol{\sigma}'] - F_{g}^{\rm as}[q\boldsymbol{\sigma}+(1-q)\boldsymbol{\sigma}'],0 \right\} \\
L001027	    &\leq \max \left\{  q\left[ g^{\rm as}(\boldsymbol{\sigma}) - F_{g}^{\rm as}(\boldsymbol{\sigma}) \right]
L001028	     + (1-q)\left[ g^{\rm as}(\boldsymbol{\sigma}') - F_{g}^{\rm as}(\boldsymbol{\sigma}') \right] ,0\right\} \\
L001029	    &\leq q\max \left\{  \ g^{\rm as}(\boldsymbol{\sigma}) - F_{g}^{\rm as} (\boldsymbol{\sigma}) ,0\right\}
L001030	     + (1-q) \max \left\{  g^{\rm as}(\boldsymbol{\sigma}') - F_{g}^{\rm as} (\boldsymbol{\sigma}'),0 \right\} \\
L001031	    &=q\mathcal{S}_{g}(\boldsymbol{\sigma}) + (1-q)\mathcal{S}_{g}(\boldsymbol{\sigma}'),\label{eq: convexity}
L001032	\end{aligned}
L001033	\end{equation}
L001034	where the third line is given by $g$ ($F_{g}^{\rm as}$) is, respectively, convex (concave), and the fourth line is the property of the maximization.
L001035	Therefore, we conclude the proof that $\mathcal{M}_{g}(\boldsymbol{M})$ is a convex functional.
L001036	
L001037	
L001038	Finally, for condition (c), we consider a post-processing $\mathcal{W}$ acting on $\boldsymbol{M}$ can be written as
L001039	\begin{equation}
L001040	\begin{aligned}
L001041	    M_{a'|x'}^T
L001042	    &=\mathcal{W}(M_{a|x}^T) \\
L001043	    &= \sum_{a,x}p(x|x')p(a'|a,x,x')M_{a|x}^T \\
L001044	    &= \sum_{a,x}p(x|x')p(a'|a,x,x')(\rho^{\rm B})^{-1/2} \,\sigma_{a|x}(\rho^{\rm B})^{-1/2} \\
L001045	    &=(\rho^{\rm B})^{-1/2} \mathcal{W}(\sigma_{a|x})(\rho^{\rm B})^{-1/2},
L001046	    \label{eq: wiring map}
L001047	\end{aligned}
L001048	\end{equation}
L001049	in which we obtain
L001050	\begin{equation}
L001051	    \sqrt{\rho^{\rm B}} \,\mathcal{W}(\boldsymbol{M})\sqrt{\rho^{\rm B}} = \mathcal{W}(\boldsymbol{\sigma}).
L001052	\end{equation}
L001053	Due to the convexity of $\mathcal{S}_{g}$, this implies  $\mathcal{S}_{g}$ is also non-increasing under post-processing, i.e., $\mathcal{S}_{g}[\mathcal{W}(\boldsymbol{\sigma})]\le \mathcal{S}_{g}(\boldsymbol{\sigma})$.
L001054	By using the above results, we can therefore show that $\mathcal{M}_{g}(\boldsymbol{M})$ is also non-increasing under $\mathcal{W}$:
L001055	\begin{equation}
L001056	\begin{aligned}
L001057	    \mathcal{M}_{g}\left[\mathcal{W}(\boldsymbol{M})\right]
L001058	    &= \sup_{\rho^{\rm B}} \mathcal{S}_{g} \left[ \sqrt{\rho^{\rm B}} \,\mathcal{W}(\boldsymbol{M})\sqrt{\rho^{\rm B}}\right] \\
L001059	    &= \mathcal{S}_{g} \left[ \sqrt{\rho^{B\star}}\, \mathcal{W}(\boldsymbol{M})\sqrt{\rho^{B\star}}\right] \\
L001060	    &= \mathcal{S}_{g} \left[ \mathcal{W}\left(\sqrt{\rho^{B\star}}\, \boldsymbol{M}\sqrt{\rho^{B\star}}\right)\right] \\
L001061	    &\leq \mathcal{S}_{g}\left(\sqrt{\rho^{B\star}}\, \boldsymbol{M}\sqrt{\rho^{B\star}}\right) \\
L001062	    &\leq \sup_{\rho^{\rm B}}\mathcal{S}_{g} \left(\sqrt{\rho^{\rm B}} \,\boldsymbol{M}\sqrt{\rho^{\rm B}}\right) \\
L001063	    &= \mathcal{M}_{g}(\boldsymbol{M}),
L001064	\end{aligned}
L001065	\end{equation}
L001066	where $\rho^{B\star}$ is the optimal argument in the supremum.
L001067	
L001068	\section{Example of qubit Pauli measurements for pure entangled state input}\label{appendix: measurement assemblage example}
L001069	
L001070	Here we illustrate the construction using qubit Pauli measurements and a pure entangled input state $\ket{\varphi^{AB}(\theta)}=\sin\theta\ket{00} + \cos\theta\ket{11}$ with noisy Pauli measurements $M_{a|x}^w=(1-w)\Pi_{a|x}+w\,\id/2$.
L001071	Taking the supremum over $\rho^{\rm B}$, we set $\theta=\pi/4$ and obtain
L001072	\begin{equation}
L001073	\begin{aligned}
L001074	    \sigma_{a|x}
L001075	    &= \Tr_{\rm A} \left(M_{a|x}^w \otimes \id  \right)\frac{1}{2}\sum_{i,j}  \ket{i}\bra{j}\otimes  \ket{i}\bra{j} \\
L001076	    &=\frac{1}{2} \sum_{i,j} \bra{j}M_{a|x}^w \ket{i} \ket{i}\bra{j}\\
L001077	    &= \frac{1}{2} M_{a|x}^w,
L001078	\end{aligned}
L001079	\end{equation}
L001080	where in the third line we used the property that the (noisy) qubit Pauli effects are Hermitian, $M_{a|x}^{w\,\dagger}=M_{a|x}^w$.
L001081	In this example the conditional probabilities are uniform, $p(a|x)=\Tr M_{a|x}^w /2=1/2$ for all $a,x$, and $\rho_{a|x}(w)=M_{a|x}^w$ is a classical mixture of the projector $\Pi_{a|x}$ and the maximally mixed state $\id/2$, with $w\in[0,1]$.
L001082	
L001083	
L001084	For $\mathcal M_N(w)$, we obtain an analytical expression that matches the known joint-measurability threshold for two Pauli measurements, namely $w\le 1-1/\sqrt{2}$~\cite{Heinosaari2008}.
L001085	Starting from the definition of $N^{\rm as}(\boldsymbol{\sigma}_x,\boldsymbol{\Pi})$ in Eq.~\eqref{eq: l2 norm}, we obtain
L001086	\begin{equation}
L001087	\begin{aligned}
L001088	    N^{\rm as}(\boldsymbol{\sigma}_x,\boldsymbol{\Pi})
L001089	    &= \sum_{a} \frac{1}{2} N\left[\rho_{a|x}(w),\boldsymbol{\Pi}\right] \\
L001090	    &= \sum_a \frac{1}{2} \sum_i \left[ \bra{i}\rho_{a|x}(w)^2\ket{i} - \bra{i}\rho_{a|x}(w)\ket{i}^2   \right] \\
L001091	    &= \sum_{a} \frac{1}{2}\sum_i \left\{ \bra{i}\left[ (1-w)^2 \Pi_{a|x} + w(1-w)\Pi_{a|x} + w^2 \frac{\id}{4} \right] \ket{i} - \left[ \bra{i}(1-w)\Pi_{a|x}\ket{i}+\frac{w}{2} \right]^2   \right\} \\
L001092	    &= \sum_{a} \frac{1}{2}  \left\{(1-w)\sum_i\left[ \bra{i}  \Pi_{a|x} \ket{i}\right]  -(1-w)^2 \sum_i \left[ \bra{i}\Pi_{a|x}\ket{i}^2 \right] - w(1-w)\sum_i\left[ \bra{i}\Pi_{a|x}\ket{i} \right]   \right\} \\
L001093	    &= \sum_{a} \frac{1}{2}  \left\{(1-w) - w(1-w) -(1-w)^2 \sum_i \bra{i}\Pi_{a|x}\ket{i}^2 \right\} \\
L001094	    &= (1-w)  - w(1-w) -  \frac{(1-w)^2}{2}\sum_{a,i}  \bra{i}\Pi_{a|x}\ket{i}^2.
L001095	\end{aligned}
L001096	\end{equation}
L001097	Similarly, substituting $\rho_{a|x}(w)$ into the concave roof $F_N$ in Eq.~\eqref{eq: F_N} yields
L001098	\begin{equation}
L001099	\begin{aligned}
L001100	     \overbar{\rm Var}^{\rm as}(\boldsymbol{\sigma}_{x'},\boldsymbol{\Pi})
L001101	     &=  \sum_{a} \frac{1}{2} \overbar{\rm Var}\left[\rho_{a|x'}(w),\boldsymbol{\Pi}\right] \\
L001102	     &=  \sum_{a} \frac{1}{2} \sum_i \left\{ \bra{i}\rho_{a|x'}(w)\ket{i} - \left[ \bra{i}\rho_{a|x'}(w)\ket{i} \right]^2 \right\} \\
L001103	     &= \sum_{a} \frac{1}{2}\left\{1 - \sum_i \bra{i} \left[ (1-w) \Pi_{a|x'} + w\frac{\id}{2} ) \right]\ket{i}^2 \right\} \\
L001104	     &= \sum_{a} \frac{1}{2}\left\{1 -(1-w)^2 \sum_i\left[ \bra{i}  \Pi_{a|x'}\ket{i}^2 \right] - w(1-w)\sum_i\left[ \bra{i}  \Pi_{a|x'}\ket{i} \right] - \frac{w^2}{2} \right\} \\
L001105	     &= 1 - \frac{w^2}{2} - w(1-w) -\frac{(1-w)^2}{2} \sum_{a,i} \bra{i}  \Pi_{a|x'}\ket{i}^2.
L001106	\end{aligned}
L001107	\end{equation}
L001108	By the definition of the violation degree, we have
L001109	\begin{equation}
L001110	\begin{aligned}
L001111	    \mathcal{M}_{N}(w)
L001112	    &= \max \left\{  \max_{x} N^{\rm as}(\boldsymbol{\sigma}_x,\boldsymbol{\Pi}) - \min_{x'} \overbar{\rm Var}^{\rm as}(\boldsymbol{\sigma}_{x'},\boldsymbol{\Pi}),0 \right\} \\
L001113	    &= \max \left\{ \frac{w^2}{2}-w - \frac{(1-w)^2}{2}\left( \min_x\sum_{a,i} \bra{i}  \Pi_{a|x}\ket{i}^2 - \max_{x'} \sum_{a,i} \bra{i}  \Pi_{a|x'}\ket{i}^2  \right),0\right\}.
L001114	\end{aligned}
L001115	\end{equation}
L001116	In the second line, the minimum (maximum) arises because the last term in $N^{\rm as}(\boldsymbol{\sigma}_x,\boldsymbol{\Pi})$ ($\overbar{\rm Var}^{\rm as}(\boldsymbol{\sigma}_{x'},\boldsymbol{\Pi})$) is negative, so the extremizers are exchanged.
L001117	Since $\{\Pi_{a|x}\}_x$ are the eigenprojectors of the Pauli $Z$ and $X$ observables, the quantity $\sum_{a,i} \bra{i}  \Pi_{a|x}\ket{i}^2$ takes the values $\{2,1\}$.
L001118	Inserting these values in and imposing $\mathcal M_g(w)\ge 0$ gives
L001119	\begin{equation}
L001120	\begin{aligned}
L001121	     0 &\leq \frac{w^2}{2} - w + \frac{(1-w)^2}{2} \\
L001122	     &= w^2 -2w + \frac{1}{2},
L001123	\end{aligned}
L001124	\end{equation}
L001125	from which we find that $\mathcal M_g(w)\ge 0$ for $w \in (-\infty ,1 - 1/\sqrt{2}]$ and for $w \in [1 + 1/\sqrt{2}, \infty )$; restricting to $w\in[0,1]$ yields the threshold $w\le 1-1/\sqrt{2}$.
L001126	
